$('imageInput').onchange=e=>{importImage(e.target.files[0]);e.target.value=''};
window.addEventListener('dragover',e=>{if(e.dataTransfer.types.includes('Files')){e.preventDefault();document.body.classList.add('drag-over')}});window.addEventListener('dragleave',e=>{if(!e.relatedTarget)document.body.classList.remove('drag-over')});window.addEventListener('drop',e=>{e.preventDefault();document.body.classList.remove('drag-over');if(e.dataTransfer.files[0])importImage(e.dataTransfer.files[0])});
function fileName(ext){return (state.name||'lineflow').replace(/[\\/:*?"<>|]/g,'-')+'.'+ext}
function download(blob,name){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),60000)}
$('saveProject').onclick=()=>{download(new Blob([JSON.stringify(state,null,2)],{type:'application/json'}),fileName('lineflow.json'));toast('工程已保存，可随时打开继续编辑')};$('openProject').onclick=()=>$('projectInput').click();
$('projectInput').onchange=async e=>{const file=e.target.files[0];e.target.value='';if(!file)return;try{if(file.size>30000000)throw Error('工程文件过大');const next=validateProject(JSON.parse(await readFile(file,'text')));if(next.backgroundData)await loadImage(next.backgroundData);askReplace(()=>{checkpoint();restoreState(next).then(()=>toast('工程已打开'))})}catch(err){toast('工程打开失败：'+err.message)}};
function outputCanvas(width,height,scene=state,image=backgroundImage,atPhase=phase){const c=document.createElement('canvas');c.width=width;c.height=height;const cx=c.getContext('2d',{willReadFrequently:true});cx.scale(width/scene.width,height/scene.height);renderScene(cx,scene,atPhase,{backgroundImage:image,editing:false});return c}
