  exportCancelled=false;$('exportTitle').textContent='正在制作你的 GIF';$('exportDetail').textContent='准备画布…';$('exportProgress').value=0;$('exportProgress').hidden=false;$('exportResult').hidden=true;$('cancelExport').textContent='取消';$('exportDialog').showModal();
  const snapshot=clone(state),image=backgroundImage,{width,height}=exportDimensions(),fps=snapshot.export.fps,count=snapshot.export.duration*fps,delay=1000/fps;
  const c=outputCanvas(width,height,snapshot,image,0),cx=c.getContext('2d',{willReadFrequently:true});let worker;
  try{worker=new Worker(new URL('./gif-worker.js',import.meta.url),{type:'module'});exportWorker=worker;const ref=cx.getImageData(0,0,width,height).data;await workerRequest(worker,{type:'init',width,height,delay,referencePixels:ref.buffer},[ref.buffer]);
    for(let i=0;i<count;i++){if(exportCancelled)throw Error('已取消');renderScene(cx,snapshot,i/count,{backgroundImage:image,editing:false});const pixels=cx.getImageData(0,0,width,height).data;const frameDelay=(Math.round((i+1)*100/fps)-Math.round(i*100/fps))*10;await workerRequest(worker,{type:'frame',index:i,pixels:pixels.buffer,delay:frameDelay},[pixels.buffer]);$('exportProgress').value=Math.round((i+1)/count*96);$('exportDetail').textContent=`正在渲染第 ${i+1} / ${count} 帧 · ${width} × ${height} px`}
    const result=await workerRequest(worker,{type:'finish'});if(exportCancelled)throw Error('已取消');const blob=new Blob([result.buffer],{type:'image/gif'});if(resultUrl)URL.revokeObjectURL(resultUrl);resultUrl=URL.createObjectURL(blob);$('exportPreview').src=resultUrl;$('downloadGif').href=resultUrl;$('downloadGif').download=fileName('gif');$('exportTitle').textContent='GIF 已准备好';$('exportDetail').textContent=`${width} × ${height} px · ${snapshot.export.duration} 秒 · ${(blob.size/1024/1024).toFixed(2)} MB`;$('exportProgress').value=100;$('exportProgress').hidden=true;$('exportResult').hidden=false;$('cancelExport').textContent='完成';
  }catch(err){if(!exportCancelled){$('exportTitle').textContent='导出未完成';$('exportDetail').textContent=err.message;$('cancelExport').textContent='关闭';$('exportProgress').hidden=true}}finally{worker?.terminate();if(exportWorker===worker)exportWorker=null}
